c='p2';B='PYTHON 4B'
def R(code,inp='',fs=22,lab='Kết quả chạy'): return RES(OUT(RUN(code,inp),fs),lab)
def V(code,inp=''): return RUN(code,inp)
S=[]
S.append(TITLE('TIN HỌC · PYTHON 4B','NGOẠI LỆ, KIỂM THỬ<br>VÀ SỬA LỖI','try – except – else – finally, assert, thiết kế bộ test, giá trị biên, tìm và sửa lỗi logic trong hàm (đề HSG).',['try','except','assert','test','sửa lỗi']))
S.append(goals(c,B,['Nhận biết <b>các loại lỗi chạy</b> (ngoại lệ) qua tên.','Dùng <b>try – except – else – finally</b> đúng thứ tự thực hiện.','Dùng <b>assert</b> và <b>raise</b>.','Thiết kế <b>bộ test</b>: bình thường, biên, đặc biệt.','<b>Tìm và sửa lỗi logic</b> thường gặp: lệch một, biên, vòng lặp vô hạn.'],['Ngoại lệ','try – except','assert, test','Sửa lỗi','Tự kiểm tra, HSG']))
S.append(TB(c,B+' · 1','Các ngoại lệ thường gặp',['Mã nguồn','Ngoại lệ','Nguyên nhân'],[['<code>a=[1,2,3]; a[3]</code>','<b>IndexError</b>','chỉ số ngoài phạm vi'],['<code>d={"a":1}; d["b"]</code>','<b>KeyError</b>','khoá không có trong dict'],['<code>int("12a")</code>','<b>ValueError</b>','giá trị không đổi được'],['<code>10 // (5 - 5)</code>','<b>ZeroDivisionError</b>','chia cho 0'],['<code>"abc" + 5</code>','<b>TypeError</b>','sai kiểu dữ liệu'],['<code>print(y + 1)</code> (y chưa gán)','<b>NameError</b>','dùng tên chưa tồn tại']],note=KEY('Dòng cuối của <b>traceback</b> luôn có dạng <b>TênLỗi: mô tả</b>. Đọc dòng này trước tiên!')))
S.append(S2(c,B+' · 1','Nhắc lại: ba loại lỗi',card('Phân loại',T(tr('Loại','Khi nào phát hiện','Ví dụ',h=True)+tr('<b>Cú pháp</b>','trước khi chạy','thiếu <b>:</b>, ngoặc')+tr('<b>Ngoại lệ</b> (chạy)','trong khi chạy','chia 0, IndexError')+tr('<b>Logic</b>','<b>không báo</b>, kết quả sai','dùng &gt; thay &gt;='))),CODE('print(10 / 0)',24)+RES(OUT(ERR('print(10 / 0)'),20),'ZeroDivisionError')+KEY('Lỗi logic là nguy hiểm nhất vì máy <b>không báo</b>: phải <b>kiểm thử</b> mới phát hiện.')))
S.append(S2(c,B+' · 2','try – except: bắt ngoại lệ',card('Cách hoạt động',STEPS(['Chạy khối <b>try</b>.','Không lỗi: <b>bỏ qua</b> mọi except.','Có lỗi: <b>dừng ngay</b> tại dòng lỗi, nhảy tới <b>except</b> khớp loại lỗi.'])+WARN('Các dòng trong try <b>sau dòng gây lỗi không chạy</b>.')),CODE('try:\n    x = int(input())\n    print(10 // x)\nexcept ValueError:\n    print("khong phai so")\nexcept ZeroDivisionError:\n    print("chia cho 0")',21)+R('try:\n    x = int(input())\n    print(10 // x)\nexcept ValueError:\n    print("khong phai so")\nexcept ZeroDivisionError:\n    print("chia cho 0")','0\n',22,'Kết quả (nhập 0)')))
S.append(S2(c,B+' · 2','else và finally',card('Thứ tự đầy đủ',ul(['<b>try</b>: đoạn có thể lỗi.','<b>except</b>: chạy khi có lỗi khớp.','<b>else</b>: chạy khi <b>không có lỗi</b>.','<b>finally</b>: <b>luôn chạy</b>, kể cả khi có return hoặc lỗi.'],7)),CODE('def chia(a, b):\n    try:\n        r = a // b\n    except ZeroDivisionError:\n        return "loi"\n    else:\n        return r\n    finally:\n        print("xong", end=" ")\nprint(chia(7, 2), chia(1, 0), chia(9, 3))',19)+R('def chia(a, b):\n    try:\n        r = a // b\n    except ZeroDivisionError:\n        return "loi"\n    else:\n        return r\n    finally:\n        print("xong", end=" ")\nprint(chia(7, 2), chia(1, 0), chia(9, 3))','',22,'Kết quả')+KEY('<b>finally</b> chạy 3 lần (in “xong” trước khi print trả giá trị); print ngoài in <b>3 loi 3</b>.')))
S.append(S2(c,B+' · 2','Thứ tự các except và sự lan truyền',card('Khớp từ trên xuống, chỉ một nhánh',P('Python kiểm tra các <b>except</b> lần lượt; <b>nhánh khớp đầu tiên</b> chạy, các nhánh sau bỏ qua.','Lỗi không khớp except nào → <b>lan ra ngoài</b> (chương trình dừng).','<code>except Exception as e</code> bắt hầu hết lỗi; <b>e</b> chứa thông báo.')),CODE('try:\n    a = [1, 2, 3]\n    x = int("7")\n    y = a[x]\n    print("A")\nexcept ValueError:\n    print("B")\nexcept IndexError:\n    print("C")\nfinally:\n    print("D")',21)+R('try:\n    a = [1, 2, 3]\n    x = int("7")\n    y = a[x]\n    print("A")\nexcept ValueError:\n    print("B")\nexcept IndexError:\n    print("C")\nfinally:\n    print("D")','',24,'Kết quả')+KEY('int("7") thành công (x = 7); <b>a[7]</b> gây IndexError → in C; finally in D. A và B <b>không in</b>.')))
S.append(S2(c,B+' · 2','Nhập đến khi đúng: vòng lặp + try',card('Kiểm tra dữ liệu người dùng',P('<b>while True</b> + <b>try</b> đọc số; thành công thì <b>break</b>; lỗi thì nhắc nhập lại.','<b>raise</b> tự phát sinh ngoại lệ để vào nhánh except.')),CODE('while True:\n    try:\n        n = int(input())\n        if n <= 0:\n            raise ValueError\n        break\n    except ValueError:\n        print("nhap lai")\nprint("n =", n)',20)+R('while True:\n    try:\n        n = int(input())\n        if n <= 0:\n            raise ValueError\n        break\n    except ValueError:\n        print("nhap lai")\nprint("n =", n)','abc\n-5\n12\n',20,'Nhập “abc”, “−5”, “12”')))
S.append(S2(c,B+' · 2','raise: tự báo lỗi trong hàm',card('Khi nào cần?',P('Hàm phát hiện <b>đầu vào không hợp lệ</b> thì nên <b>raise</b> thay vì trả giá trị vô nghĩa.','Cú pháp: <code>raise TênLỗi("thông báo")</code>.','Nơi gọi dùng try – except để xử lí.')),CODE('def can(x):\n    if x < 0:\n        raise ValueError("am")\n    return x ** 0.5\n\nfor v in (9, -4):\n    try:\n        print(can(v))\n    except ValueError as e:\n        print("loi:", e)',22)+R('def can(x):\n    if x < 0:\n        raise ValueError("am")\n    return x ** 0.5\n\nfor v in (9, -4):\n    try:\n        print(can(v))\n    except ValueError as e:\n        print("loi:", e)','',24,'Kết quả')))
# assert + test
S.append(S2(c,B+' · 3','assert: khẳng định điều kiện',card('Cú pháp',P('<code>assert điều_kiện, "thông báo"</code>: nếu điều kiện <b>sai</b> thì phát sinh <b>AssertionError</b>.','Dùng để <b>kiểm thử</b> hàm: khẳng định kết quả mong đợi.','Khi test <b>đạt</b> thì chương trình chạy bình thường, <b>không in gì</b>.')),CODE('def tb(a):\n    return sum(a) / len(a)\nkq = []\nfor t in ([2, 4], [], [5]):\n    try:\n        assert len(t) > 0, "rong"\n        kq.append(tb(t))\n    except AssertionError as e:\n        kq.append(str(e))\nprint(kq)',21)+R('def tb(a):\n    return sum(a) / len(a)\nkq = []\nfor t in ([2, 4], [], [5]):\n    try:\n        assert len(t) > 0, "rong"\n        kq.append(tb(t))\n    except AssertionError as e:\n        kq.append(str(e))\nprint(kq)','',24,'Kết quả')+KEY('Danh sách rỗng bị chặn bởi assert nên tránh được ZeroDivisionError.')))
S.append(S2(c,B+' · 3','Các loại test case',card('Cần chuẩn bị đủ loại',ul(['<b>Bình thường</b>: dữ liệu điển hình.','<b>Biên</b>: nhỏ nhất, lớn nhất, đúng mốc (0, 1, n, giá trị bằng ngưỡng).','<b>Đặc biệt</b>: rỗng, một phần tử, trùng nhau, toàn âm, đã sắp xếp, ngược.','<b>Lỗi</b>: dữ liệu sai kiểu, chia 0.'],7)+KEY('Một bộ test tốt <b>khiến mọi phiên bản sai đều lộ ra</b>.')),CODE('def xep_loai(d):\n    if d >= 8:\n        return "Gioi"\n    if d >= 6.5:\n        return "Kha"\n    if d >= 5:\n        return "TB"\n    return "Yeu"\n\nassert xep_loai(8) == "Gioi"\nassert xep_loai(7.9) == "Kha"\nassert xep_loai(6.5) == "Kha"\nassert xep_loai(5) == "TB"\nassert xep_loai(4.99) == "Yeu"\nprint("dat")',19)+R('def xep_loai(d):\n    if d >= 8:\n        return "Gioi"\n    if d >= 6.5:\n        return "Kha"\n    if d >= 5:\n        return "TB"\n    return "Yeu"\nassert xep_loai(8) == "Gioi"\nassert xep_loai(7.9) == "Kha"\nassert xep_loai(6.5) == "Kha"\nassert xep_loai(5) == "TB"\nassert xep_loai(4.99) == "Yeu"\nprint("dat")','',22,'Kết quả')))
S.append(S2(c,B+' · 3','Bộ test bắt lỗi của find_max',card('Các lỗi có thể mắc',ul(['(1) Khởi tạo <b>m = 0</b> → sai khi mọi số âm.','(2) <b>Bỏ sót phần tử cuối</b> (range(len−1)).','(3) Nhầm dấu so sánh (&lt; thay &gt;).'],7)+P('Cần <b>ít nhất</b> các test: <b>toàn số âm</b>, <b>max ở cuối</b>, <b>max ở đầu</b>, một phần tử.')),CODE('def find_max(a):\n    m = a[0]\n    for x in a:\n        if x > m:\n            m = x\n    return m\n\ntests = [([-5, -2, -9], -2), ([1, 9], 9),\n         ([9, 1], 9), ([7], 7)]\nfor a, kq in tests:\n    print(find_max(a) == kq, end=" ")',21)+R('def find_max(a):\n    m = a[0]\n    for x in a:\n        if x > m:\n            m = x\n    return m\ntests = [([-5, -2, -9], -2), ([1, 9], 9), ([9, 1], 9), ([7], 7)]\nfor a, kq in tests:\n    print(find_max(a) == kq, end=" ")','',22,'Hàm đúng: mọi test đạt')+KEY('Thử với phiên bản sai <b>m = 0</b>: test toàn âm trả 0 ≠ −2 → <b>bị phát hiện</b>.')))
S.append(S2(c,B+' · 3','Bộ test bắt lỗi của index_of',card('Hàm tìm vị trí',CODE('def index_of(a, k):\n    for i in range(len(a)):\n        if a[i] == k:\n            return i\n    return -1',20)+P('Các lỗi có thể: bỏ sót <b>phần tử cuối</b>; bỏ sót <b>phần tử đầu</b>; trả về <b>vị trí cuối</b> thay vì vị trí đầu khi có trùng; không trả −1.')),CODE('tests = [([5, 6, 7], 5),   # đầu\n         ([5, 6, 7], 7),   # cuối\n         ([5, 6, 5], 5),   # trùng: kỳ vọng 0\n         ([5, 6, 7], 9),   # không có: -1\n         ([], 1)]          # rỗng\ndef index_of(a, k):\n    for i in range(len(a)):\n        if a[i] == k:\n            return i\n    return -1\nprint([index_of(a, k) for a, k in tests])',19)+R('tests = [([5, 6, 7], 5), ([5, 6, 7], 7), ([5, 6, 5], 5), ([5, 6, 7], 9), ([], 1)]\ndef index_of(a, k):\n    for i in range(len(a)):\n        if a[i] == k:\n            return i\n    return -1\nprint([index_of(a, k) for a, k in tests])','',22,'Kết quả: mong đợi [0, 2, 0, −1, −1]')))
# sửa lỗi
S.append(S2(c,B+' · 4','Lỗi “lệch một” (off-by-one)',card('Hàm đếm số chẵn bị sai',CODE('def dem_chan(a):\n    dem = 0\n    for i in range(len(a) - 1):\n        if a[i] % 2 == 0:\n            dem += 1\n    return dem',21)+P('<b>Lỗi</b>: <code>range(len(a) − 1)</code> chỉ chạy i = 0 … n−2, <b>bỏ sót phần tử cuối</b>.','<b>Sửa</b>: <code>range(len(a))</code>, hoặc duyệt trực tiếp <code>for x in a</code>.')),R('def dem_chan(a):\n    dem = 0\n    for i in range(len(a) - 1):\n        if a[i] % 2 == 0:\n            dem += 1\n    return dem\nprint(dem_chan([2, 4, 6]), dem_chan([1, 2]))','',24,'Hàm sai: mong đợi 3 và 1')+KEY('Test lộ lỗi: số chẵn <b>nằm ở cuối</b> dãy. Luôn có test mà đáp án phụ thuộc vào phần tử cuối.')))
S.append(S2(c,B+' · 4','Lỗi biên trong kiểm tra nguyên tố',card('Hàm sai với vài số đầu',CODE('def nt(n):\n    if n < 2:\n        return False\n    for i in range(2, int(n ** 0.5)):\n        if n % i == 0:\n            return False\n    return True',21)+P('<b>Lỗi</b>: <code>range(2, int(√n))</code> <b>không lấy</b> int(√n). Với n = 4, 9, 25… (bình phương số nguyên tố) bỏ sót ước √n → <b>kết luận sai là nguyên tố</b>.','<b>Sửa</b>: <code>range(2, int(n ** 0.5) + 1)</code>.')),R('def nt(n):\n    if n < 2:\n        return False\n    for i in range(2, int(n ** 0.5)):\n        if n % i == 0:\n            return False\n    return True\nprint([n for n in range(1, 30) if nt(n)])','',20,'Danh sách bị lẫn hợp số 4, 9, 25')+KEY('Bộ test cần các <b>số chính phương</b> (4, 9, 25) và các số bé (1, 2, 3).')))
S.append(S2(c,B+' · 4','Lỗi chỉ số và logic trong xâu đối xứng',card('Hàm sai hai chỗ',CODE('def la_palindrome(s):\n    t = s.replace(" ", "")\n    for i in range(len(t) // 2):\n        if t[i] == t[len(t) - i]:\n            return False\n    return True',20)+P('<b>Lỗi 1</b>: <code>t[len(t) − i]</code> với i = 0 → <b>t[len(t)]</b>: <b>IndexError</b>. Phải là <code>t[len(t) − 1 − i]</code>.','<b>Lỗi 2</b>: điều kiện <b>ngược</b>: hai kí tự đối xứng <b>bằng nhau</b> là tốt, phải return False khi <b>khác nhau</b>.')),R('def f(s):\n    t = s.replace(" ", "")\n    for i in range(len(t) // 2):\n        if t[i] != t[len(t) - 1 - i]:\n            return False\n    return True\nprint(f("abba"), f("abca"), f("a b a"))','',24,'Hàm đã sửa')))
S.append(S2(c,B+' · 4','Vòng lặp vô hạn trong tìm kiếm nhị phân',card('Hàm sai: có lúc không dừng',CODE('def tim(a, k):\n    l, r = 0, len(a) - 1\n    while l <= r:\n        m = (l + r) // 2\n        if a[m] == k:\n            return m\n        elif a[m] < k:\n            l = m\n        else:\n            r = m - 1\n    return -1',20)+P('<b>Lỗi</b>: <code>l = m</code> không loại m khỏi khoảng tìm. Với a = [1, 3], k = 3... khi l = m thì khoảng <b>không thu hẹp</b> → lặp vô hạn.','<b>Sửa</b>: <code>l = m + 1</code> (m đã xét, bỏ đi).')),R('def tim(a, k):\n    l, r = 0, len(a) - 1\n    while l <= r:\n        m = (l + r) // 2\n        if a[m] == k:\n            return m\n        elif a[m] < k:\n            l = m + 1\n        else:\n            r = m - 1\n    return -1\nprint(tim([1, 3, 5, 7, 9], 7), tim([1, 3, 5], 4))','',24,'Hàm đã sửa')+KEY('Quy tắc: mỗi vòng lặp phải <b>thu hẹp</b> miền tìm; luôn <b>±1</b> sau khi đã xét m.')))
S.append(S2(c,B+' · 4','Quy trình gỡ lỗi',card('Năm bước',STEPS(['<b>Đọc thông báo lỗi</b>, xác định dòng và loại lỗi.','<b>Tái hiện</b> lỗi bằng dữ liệu nhỏ nhất.','<b>Theo dõi</b>: in giá trị biến hoặc lập bảng trace bằng tay.','<b>Giả thuyết</b> chỗ sai, sửa <b>một chỗ</b> mỗi lần.','<b>Chạy lại toàn bộ test</b> để chắc không phát sinh lỗi mới.'])),CODE('def tong_chan(a):\n    s = 0\n    for x in a:\n        if x % 2 == 0:\n            s += x\n        print("DEBUG x =", x, "s =", s)\n    return s\nprint(tong_chan([3, 4, 6]))',21)+R('def tong_chan(a):\n    s = 0\n    for x in a:\n        if x % 2 == 0:\n            s += x\n        print("DEBUG x =", x, "s =", s)\n    return s\nprint(tong_chan([3, 4, 6]))','',22,'Dùng print để theo dõi')))
S.append(SELF(c,B+' · 5','Tự kiểm tra: thứ tự try – except – finally','Chương trình in ra gì? Nếu thay <code>int("7")</code> bằng <code>int("x")</code> thì sao?','try:\n    a = [1, 2, 3]\n    x = int("7")\n    y = a[x]\n    print("A")\nexcept ValueError:\n    print("B")\nexcept IndexError:\n    print("C")\nfinally:\n    print("D")',P('<b>Ban đầu</b>: x = 7; <code>a[7]</code> gây <b>IndexError</b> → nhánh C, rồi finally D. In: <b>C D</b>.','<b>Nếu int("x")</b>: gây <b>ValueError</b> ngay → nhánh B, rồi finally D. In: <b>B D</b>. Dòng “A” không bao giờ in vì luôn có lỗi trước.')+R('try:\n    a = [1, 2, 3]\n    x = int("x")\n    y = a[x]\n    print("A")\nexcept ValueError:\n    print("B")\nexcept IndexError:\n    print("C")\nfinally:\n    print("D")','',24,'Kết quả thật với int("x")'),20))
S.append(SELF(c,B+' · 5','Tự kiểm tra (HSG): chọn bộ test','Hàm đếm số lần xuất hiện lớn nhất của một giá trị liên tiếp trong dãy. Hãy nêu 5 test để phát hiện nhiều lỗi nhất.','def dai_nhat(a):\n    best = cur = 1\n    for i in range(1, len(a)):\n        cur = cur + 1 if a[i] == a[i - 1] else 1\n        best = max(best, cur)\n    return best',P('<b>Test 1</b> [5]: một phần tử → 1 (hàm cho 1, nhưng dãy <b>rỗng</b> sẽ lỗi IndexError ở chỗ khác).','<b>Test 2</b> [2,2,2,2]: toàn bằng nhau → 4 (dãy dài nhất ở cuối).','<b>Test 3</b> [1,2,3]: không có cặp bằng nhau → 1.','<b>Test 4</b> [3,3,1,1,1,2]: dãy dài nhất ở giữa → 3.','<b>Test 5</b> [1,1,1,2,2]: dài nhất ở đầu → 3. Thêm <b>[]</b> (rỗng): cần quy ước kết quả 0.')+R('def dai_nhat(a):\n    best = cur = 1\n    for i in range(1, len(a)):\n        cur = cur + 1 if a[i] == a[i - 1] else 1\n        best = max(best, cur)\n    return best\nfor t in ([5], [2,2,2,2], [1,2,3], [3,3,1,1,1,2], [1,1,1,2,2]):\n    print(dai_nhat(t), end=" ")','',22,'Kết quả thật'),19))
S+=END(c,B,['<b>Ngoại lệ</b>: IndexError, KeyError, ValueError, ZeroDivisionError, TypeError, NameError.','<b>try</b> chạy; có lỗi → <b>except</b> khớp đầu tiên; không lỗi → <b>else</b>; <b>finally</b> luôn chạy.','<b>raise</b> tự phát sinh lỗi; <b>assert</b> khẳng định điều kiện.','Bộ test: <b>bình thường, biên, đặc biệt</b>.','Lỗi hay gặp: <b>lệch một</b>, thiếu <b>+1</b> ở range, biên &gt; và &gt;=, vòng lặp không thu hẹp.','Gỡ lỗi: đọc lỗi → tái hiện → theo dõi → sửa một chỗ → test lại.'],[('Chia 0','ZeroDivisionError'),('Luôn chạy','finally'),('Khẳng định','assert'),('Tự báo lỗi','raise')],'Bắt lỗi quá rộng che mất lỗi thật; sửa nhiều chỗ cùng lúc; thiếu test biên.',['Dòng sau chỗ lỗi trong try <b>không chạy</b>.','<b>finally</b> chạy cả khi có return.','Test phải có <b>phần tử cuối, phần tử đầu, rỗng</b>.','Với số chính phương, <code>range(2, int(√n)+1)</code>.'],['<b>Ngoại lệ tự định nghĩa</b> (class).','<b>unittest, pytest</b>.','<b>Logging</b> thay print khi gỡ lỗi.'],
 [('Lỗi gì: <code>int("3.5")</code>?',),('Lỗi gì: <code>[1,2][2]</code>?',),('Nhánh nào luôn chạy: try, except, else hay finally?',),('<code>assert 2 + 2 == 5</code> gây lỗi gì?',),('<code>except Exception as e</code>: e dùng để làm gì?',)],
 [('<b>ValueError</b>.',),('<b>IndexError</b>.',),('<b>finally</b>.',),('<b>AssertionError</b>.',),('Lấy thông báo lỗi (in ra, ghi lại).',)],
 [('Mức 1. Đọc một số nguyên, nếu nhập sai thì in “Loi” và dừng. Thử “12”, “abc”.',),('Mức 1. Hàm <code>chia_an_toan(a, b)</code> trả None nếu b = 0.',),('Mức 2. Viết bộ <code>assert</code> kiểm thử hàm <code>la_nt(n)</code> với các biên 0, 1, 2, 4, 9, 97.',),('Mức 2. Hàm sau có lỗi, hãy tìm và sửa: tính tổng các số từ 1 đến n bằng <code>for i in range(1, n)</code>.',),('Mức 3 (HSG). Hàm <code>vi_tri_dau(a, k)</code> tìm vị trí <b>đầu tiên</b> của k trong mảng tăng có giá trị trùng bằng nhị phân; hãy sửa để không trả về vị trí giữa chừng.',),('Mức 3 (HSG). Hàm đọc dãy số có thể chứa chữ: bỏ qua phần tử không phải số, trả tổng và <b>số phần tử lỗi</b>. Thử “3 x 4 5.5 y 6”.',)],
 [('<code>try: n = int(input()); print(n)\\nexcept ValueError: print("Loi")</code>.',),('<code>return None if b == 0 else a / b</code>.',),('<code>assert not nt(0) and not nt(1) and nt(2) and not nt(4) and not nt(9) and nt(97)</code>.',),('Lỗi lệch một: phải là <code>range(1, n + 1)</code>.',),('Khi a[m] == k, <b>không return</b> mà đặt <code>kq = m; r = m − 1</code> để tiếp tục tìm bên trái → '+V('def f(a,k):\n    l,r,kq=0,len(a)-1,-1\n    while l<=r:\n        m=(l+r)//2\n        if a[m]==k: kq=m; r=m-1\n        elif a[m]<k: l=m+1\n        else: r=m-1\n    return kq\nprint(f([1,2,2,2,3],2), f([1,3],2))')+'.',),('Dùng try – except ValueError cho từng phần tử → '+V('s="3 x 4 5.5 y 6"\nt=0;e=0\nfor w in s.split():\n    try: t+=float(w)\n    except ValueError: e+=1\nprint(t,e)')+'.',)],hper=2)
mkdeck('p4b.html','Python 4B · Ngoại lệ, kiểm thử và sửa lỗi',S)
